@pytest.mark.parametrize(
    "value, expected",
    [
        (0, "0 Bytes"),
        (2, "2 Bytes"),
        (999, "999 Bytes"),
        (1000, "1000 Bytes"),
        (1023, "1023 Bytes"),
    ],
)
def test_r3_binary_below_base_1024_returns_bytes(value, expected):
