# ---------------------------------------------------------------------------
# R5: binary=True, base 1024, sufixos KiB..QiB
# ---------------------------------------------------------------------------

@pytest.mark.parametrize(
    "value, expected",
    [
        (1024, "1.0 KiB"),
        (1025, "1.0 KiB"),
        (1536, "1.5 KiB"),
        (3000, "2.9 KiB"),
        (4096, "4.0 KiB"),
